Rule.Source:
import java.text.SimpleDateFormat;
import java.util.Date;
import sailpoint.object.Identity;
import sailpoint.object.Link;
import sailpoint.tools.Util;

// IMPORTANT: in BeanShell an unbound argument is "void", not null.
// A plain (link != null) triggers the error itself, because
// resolving the undefined variable already fails:
//     bsh.EvalError: ... on undefined variable or class name: link
//
// This rule runs from two contexts: during aggregation (link bound)
// and during identity refresh without an account (link undefined).
// Hence check for void first and normalize to a local variable.
Link hrLink = null;
if (link != void && link != null) {
    hrLink = link;
}
Identity ident = null;
if (identity != void && identity != null) {
    ident = identity;
}

// The values are on the HR link, not on the identity: this rule
// runs during attribute computation, so the identity is not yet
// fully populated at that point.
//
// Link has NO getStringAttribute(), only Identity has. On the link
// use getAttribute() with a cast (checked against the running 8.5).
String start = null;
String end  = null;

if (hrLink != null) {
    start = (String) hrLink.getAttribute("startDate");
    end  = (String) hrLink.getAttribute("endDate");
}
if (Util.isNullOrEmpty(start) && ident != null) {
    start = ident.getStringAttribute("startDate");
}
if (Util.isNullOrEmpty(end) && ident != null) {
    end = ident.getStringAttribute("endDate");
}

// No dates, no verdict: do not lock.
if (Util.isNullOrEmpty(start) && Util.isNullOrEmpty(end)) {
    return Boolean.FALSE;
}

SimpleDateFormat fmt = new SimpleDateFormat("yyyy-MM-dd");
fmt.setLenient(false);

// Truncate to day precision: otherwise an end date of today would
// count differently depending on the time of day.
java.util.Calendar cal = java.util.Calendar.getInstance();
cal.set(java.util.Calendar.HOUR_OF_DAY, 0);
cal.set(java.util.Calendar.MINUTE, 0);
cal.set(java.util.Calendar.SECOND, 0);
cal.set(java.util.Calendar.MILLISECOND, 0);
Date today = cal.getTime();

// Start still pending.
if (Util.isNotNullOrEmpty(start)) {
    try {
        Date startDay = fmt.parse(start);
        if (startDay.after(today)) {
            return Boolean.TRUE;
        }
    } catch (Exception e) {
        // Do not treat an unparseable date as a lock reason: a typo
        // in the source must not lock anyone out.
    }
}

// End reached or passed.
if (Util.isNotNullOrEmpty(end)) {
    try {
        Date endDay = fmt.parse(end);
        if (!endDay.after(today)) {
            return Boolean.TRUE;
        }
    } catch (Exception e) {
        // see above
    }
}

return Boolean.FALSE;

import sailpoint.object.Identity;
import sailpoint.tools.Util;

// Unbound arguments are "void" in BeanShell, not null.
Identity current = null;
if (newIdentity != void && newIdentity != null) {
    current = newIdentity;
}
Identity previous = null;
if (previousIdentity != void && previousIdentity != null) {
    previous = previousIdentity;
}

if (current == null) {
    return false;
}

// The transition from active to locked.
boolean becameInactive = (previous == null || !previous.isInactive())
                        && current.isInactive();
if (!becameInactive) {
    return false;
}

// Decisive: only with a set end date is this a departure. For a
// start not yet reached the field is null.
String end = current.getStringAttribute("endDate");
return Util.isNotNullOrEmpty(end);

import java.util.ArrayList;
import java.util.List;
import sailpoint.object.Application;
import sailpoint.object.Filter;
import sailpoint.object.Identity;
import sailpoint.object.Link;
import sailpoint.object.QueryOptions;
import sailpoint.tools.Util;

// Unbound arguments are "void" in BeanShell, not null. Which of
// them are bound depends on the caller (policy evaluation, form
// refresh, runRule from another script), so every optional one is
// normalized first.
Identity ident = null;
if (identity != void && identity != null) {
    ident = identity;
}
Application app = null;
if (application != void && application != null) {
    app = application;
}
if (ident == null) {
    return null;
}

String first = ident.getFirstname();
String last  = ident.getLastname();
String base;
if (Util.isNotNullOrEmpty(first) && Util.isNotNullOrEmpty(last)) {
    base = (first.substring(0, 1) + last).toLowerCase();
} else {
    base = ident.getName().toLowerCase();
}
base = base.replaceAll("[^a-z0-9]", "");
if (base.length() == 0) {
    base = ident.getName().toLowerCase().replaceAll("[^a-z0-9]", "");
}

// Without an application there is nothing to check against.
if (app == null) {
    return base;
}

String empNo = ident.getStringAttribute("employeeNumber");
if (empNo == null) {
    empNo = "";
}
String last2 = (empNo.length() >= 2)
             ? empNo.substring(empNo.length() - 2) : empNo;

List candidates = new ArrayList();
candidates.add(base);
candidates.add(base + last2);
candidates.add(base + empNo);

String chosen = base;
for (String candidate : candidates) {
    QueryOptions qo = new QueryOptions();
    qo.add(Filter.eq("application", app));
    qo.add(Filter.like("nativeIdentity", "uid=" + candidate + ",",
                       Filter.MatchMode.START));
    if (ident.getId() != null) {
        qo.add(Filter.ne("identity", ident));
    }
    chosen = candidate;
    if (context.countObjects(Link.class, qo) == 0) {
        break;
    }
}
return chosen;
